"""Teaching sections: ATP, enzyme, redox."""
import math
from guide_kit import T, R, B, box, section, arrow, svg, txt


def hexa(cx, cy, r, fill, stroke="#6b3fa0"):
    pts = " ".join(f"{cx + r * math.cos(math.radians(60 * i + 30)):.0f},{cy + r * math.sin(math.radians(60 * i + 30)):.0f}"
                   for i in range(6))
    return f'<polygon points="{pts}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'


